package cn.zhuatech.apautomation.deep;import cn.zhuatech.apautomation.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/ap") public class DeepDomainController{private final DeepDomainService s;public DeepDomainController(DeepDomainService s){this.s=s;}@GetMapping("/dashboard")ApiResponse<?> dashboard(@RequestParam String organizationCode){return ApiResponse.ok(s.dashboard(organizationCode));}@PostMapping("/purchase-order-lines")ApiResponse<?> po(@Valid @RequestBody DeepDomainService.PoLineRequest r){return ApiResponse.ok(s.createPo(r));}@PostMapping("/purchase-order-lines/{id}/receipts")ApiResponse<?> receipt(@PathVariable Long id,@Valid @RequestBody DeepDomainService.ReceiptRequest r){return ApiResponse.ok(s.receive(id,r));}@PostMapping("/invoices")ApiResponse<?> invoice(@Valid @RequestBody DeepDomainService.InvoiceRequest r){return ApiResponse.ok(s.createInvoice(r));}@PostMapping("/invoices/{id}/match")ApiResponse<?> match(@PathVariable Long id,@Valid @RequestBody DeepDomainService.MatchRequest r){return ApiResponse.ok(s.match(id,r));}}
